import type { Dispatch, SetStateAction } from "react";
import type { ChatMessage } from "@/lib/chatTranscriptMerge";
import { briefApi, makeFileContextItem, type ContextItem } from "@/lib/context";

type AssistantMessage = Extract<ChatMessage, { role: "assistant" }>;

// Construct these callbacks outside ChatPanel's render scope. Memoized callbacks
// with different lifetimes can otherwise keep prior shared render contexts (and
// their timelines) reachable through one another in V8.
export function createAttachContextPath(setContextItems: Dispatch<SetStateAction<ContextItem[]>>) {
  return (path: string, sizeBytes = 0) => {
    setContextItems((prev) => {
      if (prev.some((item) => item.source_path === path)) return prev;
      return [...prev, makeFileContextItem(path, sizeBytes)];
    });
  };
}

export function createPromoteToBrief(
  sessionId: string | null,
  fetchExactAssistant: (message: AssistantMessage) => Promise<string>,
) {
  return (message: AssistantMessage) => {
    if (!sessionId) return;
    void fetchExactAssistant(message).then((text) => briefApi.get(sessionId).then((response) => {
      const current = response.text.trim();
      const appended = current ? `${current}\n\n${text}` : text;
      return briefApi.set(sessionId, appended);
    })).catch(() => {});
  };
}

import { afterEach, describe, expect, it, vi } from "vitest";
import type { SetStateAction } from "react";
import { briefApi, type ContextItem } from "@/lib/context";
import { createAttachContextPath, createPromoteToBrief } from "./chatContextCallbacks";

afterEach(() => vi.restoreAllMocks());

describe("chat context callbacks", () => {
  it("attaches to the latest draft and preserves duplicate identity", () => {
    let items: ContextItem[] = [];
    const attach = createAttachContextPath((update: SetStateAction<ContextItem[]>) => {
      items = typeof update === "function" ? update(items) : update;
    });
    attach("/tmp/first.txt", 42);
    const first = items;
    attach("/tmp/first.txt", 99);
    expect(items).toBe(first);
    attach("/tmp/second.txt");
    expect(items).toHaveLength(2);
    expect(items[0]).toMatchObject({ source_path: "/tmp/first.txt", size_bytes: 42 });
    expect(items[1]).toMatchObject({ source_path: "/tmp/second.txt", size_bytes: 0 });
  });

  it("keeps separate draft owners when an older callback is still referenced", () => {
    const oldSetter = vi.fn();
    const newSetter = vi.fn();
    const oldAttach = createAttachContextPath(oldSetter);
    const newAttach = createAttachContextPath(newSetter);
    newAttach("/tmp/new.txt");
    oldAttach("/tmp/old.txt");
    expect(oldSetter).toHaveBeenCalledTimes(1);
    expect(newSetter).toHaveBeenCalledTimes(1);
    expect(oldSetter.mock.calls[0][0]([])[0].source_path).toBe("/tmp/old.txt");
    expect(newSetter.mock.calls[0][0]([])[0].source_path).toBe("/tmp/new.txt");
  });

  it("promotes exact content to the invoking session after a thread switch", async () => {
    let resolveExact!: (text: string) => void;
    const exact = vi.fn(() => new Promise<string>((resolve) => { resolveExact = resolve; }));
    const get = vi.spyOn(briefApi, "get").mockResolvedValue({ session_id: "old", text: "  Existing brief  " });
    const set = vi.spyOn(briefApi, "set").mockResolvedValue({ session_id: "old", text: "saved" });
    const promoteOld = createPromoteToBrief("old", exact);
    const promoteNew = createPromoteToBrief("new", vi.fn(async () => "new answer"));
    const message = { id: "answer", role: "assistant" as const, content: "preview", liveOmittedChars: 100 };
    promoteOld(message);
    expect(get).not.toHaveBeenCalled();
    resolveExact("complete answer");
    await vi.waitFor(() => expect(set).toHaveBeenCalledWith("old", "Existing brief\n\ncomplete answer"));
    expect(exact).toHaveBeenCalledWith(message);
    expect(get).toHaveBeenCalledWith("old");
    expect(promoteNew).not.toBe(promoteOld);
  });

  it("starts an empty brief without leading separators", async () => {
    vi.spyOn(briefApi, "get").mockResolvedValue({ session_id: "session", text: " \n " });
    const set = vi.spyOn(briefApi, "set").mockResolvedValue({ session_id: "session", text: "answer" });
    createPromoteToBrief("session", async () => "answer")({ id: "answer", role: "assistant", content: "answer" });
    await vi.waitFor(() => expect(set).toHaveBeenCalledWith("session", "answer"));
  });

  it("does nothing without a session and contains a failed exact-content request", async () => {
    const get = vi.spyOn(briefApi, "get");
    const set = vi.spyOn(briefApi, "set");
    const exact = vi.fn(async () => { throw new Error("unavailable"); });
    const message = { id: "answer", role: "assistant" as const, content: "answer" };
    createPromoteToBrief(null, exact)(message);
    expect(exact).not.toHaveBeenCalled();
    createPromoteToBrief("session", exact)(message);
    await Promise.resolve();
    await Promise.resolve();
    expect(get).not.toHaveBeenCalled();
    expect(set).not.toHaveBeenCalled();
  });
});

