import type { Dispatch, SetStateAction } from "react";
import type { ChatMessage } from "@/lib/chatTranscriptMerge";
import { briefApi, makeFileContextItem, type ContextItem } from "@/lib/context";

type AssistantMessage = Extract<ChatMessage, { role: "assistant" }>;

// Construct these callbacks outside ChatPanel's render scope. Memoized callbacks
// with different lifetimes can otherwise keep prior shared render contexts (and
// their timelines) reachable through one another in V8.
export function createAttachContextPath(setContextItems: Dispatch<SetStateAction<ContextItem[]>>) {
  return (path: string, sizeBytes = 0) => {
    setContextItems((prev) => {
      if (prev.some((item) => item.source_path === path)) return prev;
      return [...prev, makeFileContextItem(path, sizeBytes)];
    });
  };
}

export function createPromoteToBrief(
  sessionId: string | null,
  fetchExactAssistant: (message: AssistantMessage) => Promise<string>,
) {
  return (message: AssistantMessage) => {
    if (!sessionId) return;
    void fetchExactAssistant(message).then((text) => briefApi.get(sessionId).then((response) => {
      const current = response.text.trim();
      const appended = current ? `${current}\n\n${text}` : text;
      return briefApi.set(sessionId, appended);
    })).catch(() => {});
  };
}

export function createTurnIndexForMessageIndex(messages: readonly ChatMessage[]) {
  return (messageIndex: number) => {
    let turnIndex = 0;
    for (let index = 0; index <= messageIndex && index < messages.length; index += 1) {
      if (messages[index]?.role === "user") turnIndex += 1;
    }
    return Math.max(0, turnIndex - 1);
  };
}

