import type { ChatMessage } from "@/lib/chatTranscriptMerge";

// Construct the lookup outside ChatPanel's render scope so its memoized lifetime
// cannot keep other render-local callbacks and prior timelines reachable in V8.
export function createTurnIndexForMessageIndex(messages: readonly ChatMessage[]) {
  return (messageIndex: number) => {
    let turnIndex = 0;
    for (let index = 0; index <= messageIndex && index < messages.length; index += 1) {
      if (messages[index]?.role === "user") turnIndex += 1;
    }
    return Math.max(0, turnIndex - 1);
  };
}

import { describe, expect, it } from "vitest";
import { createTurnIndexForMessageIndex } from "./chatTimelineCallbacks";

describe("timeline search position lookup", () => {
  it("maps message positions to user turns, including partial histories", () => {
    const lookup = createTurnIndexForMessageIndex([
      { id: "partial", role: "assistant", content: "partial earlier turn" },
      { id: "u1", role: "user", content: "first question" },
      { id: "a1", role: "assistant", content: "first answer" },
      { id: "note", role: "note", text: "work" },
      { id: "u2", role: "user", content: "second question" },
      { id: "a2", role: "assistant", content: "second answer" },
    ]);
    expect([-1, 0, 1, 2, 3, 4, 5, 100].map(lookup)).toEqual([0, 0, 0, 0, 0, 1, 1, 1]);
    expect(createTurnIndexForMessageIndex([])(10)).toBe(0);
  });

  it("keeps each transcript lookup bound to its own message positions", () => {
    const first = createTurnIndexForMessageIndex([
      { id: "u1", role: "user", content: "one" },
      { id: "u2", role: "user", content: "two" },
    ]);
    const second = createTurnIndexForMessageIndex([
      { id: "u3", role: "user", content: "another chat" },
      { id: "a3", role: "assistant", content: "answer" },
    ]);
    expect(first(1)).toBe(1);
    expect(second(1)).toBe(0);
    expect(first(1)).toBe(1);
  });
});
